"""API-Definition EduKSX-Sign. Persönliche Ablage unter /api/v1/me/…, Prozesse und Siegel unter /api/v1/org/…"""

M, O = "/api/v1/me", "/api/v1/org"


def R(tabelle, schema, op, op_mehrzahl, einzahl, mehrzahl, basis, **kw):
    return {"tabelle": tabelle, "schema": schema, "op": op, "op_mehrzahl": op_mehrzahl, "einzahl": einzahl, "mehrzahl": mehrzahl,
            "pfad": f"{basis}/{kw.pop('pfad', tabelle.replace('_', '-'))}", **kw}


STUFE = "enum:simple=einfach (SES);advanced=fortgeschritten (FES);qualified=qualifiziert (QES)"
RAUM = "enum:zertes=Schweiz (ZertES);eidas=EU (eIDAS)"

API = {
    "titel": "EduKSX-Sign",
    "beschreibung": "Signatur und persönliche Ablage: Ordner und Dokumente je Person, Anmerkungen und Formulare, Word inline, Umwandlung in "
                    "PDF/A, Signaturprozesse (SES/FES/QES, ZertES/eIDAS) mit Ergebnis «_sign» im Ursprungsordner, Versiegeln mit dem "
                    "Organisationssiegel («_seal»), Anfragen aus anderen Modulen und Abgleich mit der Cloud-Ablage.",
    "tags": {
        "folders": "Ordner der persönlichen Ablage", "documents": "Dokumente", "annotations": "Anmerkungen und Formulare",
        "signature-processes": "Signaturprozesse", "signature-requests": "Zu unterschreiben", "seals": "Versiegeln und prüfen",
        "sync": "Abgleich mit der Cloud-Ablage", "preferences": "Meine Unterschrift",
    },
    "ressourcen": [
        R("folders", "Folder", "Folder", "Folders", "Ordner", "Ordner", M, filter=["parent_id"], artikel="einen", nur_lesen=["user_id", "system_folder"],
          berechnet={"path": ("text", "Pfad", "«Meine Ablage / …»"), "document_count": ("int", "Dokumente", "inkl. Unterordner")},
          loeschtext="Ordner in den Papierkorb; nicht leere Ordner nur mit Bestätigung."),
        R("documents", "Document", "Document", "Documents", "Dokument", "Dokumente", M, filter=["folder_id", "document_type", "status", "q"], ops="lrud",
          nur_lesen=["user_id", "document_type", "mime_type", "size_bytes", "status", "is_locked", "derived_from_id", "derivation", "sync_status", "current_version", "content_changed_at"],
          berechnet={"signatures": ("list:ref:SignatureProof", "Signaturen", "Nachweise"), "seal": ("ref:SealProof?", "Siegel", "falls versiegelt")}),
        R("signature_processes", "SignatureProcess", "SignatureProcess", "SignatureProcesses", "Signaturprozess", "Signaturprozesse", O, filter=["status"], artikel="einen",
          nur_lesen=["number", "status", "is_converted", "has_placeholders", "result_document_id", "provider_reference", "source_module", "source_reference", "sent_at", "completed_at", "initiator_id"],
          eingebettet={"participants": ("list:ref:Participant", "Beteiligte", "unterschreiben, genehmigen oder Kopie"), "fields": ("list:ref:SignatureField", "Unterschriftsfelder", "je Person")},
          berechnet={"events": ("list:ref:ProcessEvent", "Signaturprotokoll", "unveränderlich")}, loeschtext="Entwurf verwerfen."),
    ],
    "schemas": {
        "Participant": {"title": "Beteiligte Person", "description": "Person im Signaturprozess",
                        "felder": {"user_id": ("uuid?", "Person", "intern; sonst leer"), "display_name": ("text", "Name", "Anzeige"), "email": ("email", "E-Mail", "Einladung"),
                                   "mobile_number": ("text?", "Mobiltelefon", "Code für FES"), "participant_role": ("enum:signer=unterschreiben;approver=genehmigen;copy=Kopie erhalten", "Rolle", "Aufgabe"),
                                   "position": ("int", "Reihenfolge", "bei «nacheinander»"),
                                   "status": ("enum:open=offen;notified=benachrichtigt;signed=signiert;approved=genehmigt;declined=abgelehnt!", "Status", "Stand der Person")},
                        "pflicht": ["display_name", "email", "participant_role"]},
        "SignatureField": {"title": "Unterschriftsfeld", "description": "Feld einer Person auf dem Dokument",
                           "felder": {"participant_position": ("int", "Person", "Reihenfolge der Person"), "page_index": ("int", "Seite", "ab 0"),
                                      "x_percent": ("decimal", "Position links (%)", "relativ"), "y_percent": ("decimal", "Position oben (%)", "relativ"),
                                      "width_percent": ("decimal", "Breite (%)", "relativ"), "height_percent": ("decimal", "Höhe (%)", "relativ"), "placeholder": ("text?", "Platzhalter", "aus «#sign#n#»")},
                           "pflicht": ["participant_position", "page_index", "x_percent", "y_percent"]},
        "ProcessEvent": {"title": "Protokolleintrag", "description": "Eintrag im Signaturprotokoll",
                         "felder": {"occurred_at": ("datetime", "Zeitpunkt", "wann"), "text": ("text", "Eintrag", "Vorgang")}},
        "SignatureProof": {"title": "Signatur", "description": "Nachweis einer Signatur",
                           "felder": {"signer_name": ("text", "Name", "wie im Zertifikat"), "signer_function": ("text?", "Funktion", "Anzeige"), "signature_level": (STUFE, "Signaturstufe", "rechtliche Wirkung"),
                                      "jurisdiction": (RAUM, "Rechtsraum", "Signaturrecht"), "signed_at": ("datetime", "Zeitpunkt", "Zeitstempel"), "is_valid": ("bool?", "Gültig", "Prüfbericht")}},
        "SealProof": {"title": "Siegel", "description": "Siegel der Organisation",
                      "felder": {"seal_holder": ("text", "Organisation", "Inhaberin"), "seal_level": ("enum:advanced=fortgeschritten;qualified=qualifiziert", "Stufe", "rechtliche Wirkung"),
                                 "jurisdiction": (RAUM, "Rechtsraum", "Signaturrecht"), "is_visible": ("bool", "Sichtbar", "Siegelbild"), "sealed_at": ("datetime", "Versiegelt am", "Zeitstempel")}},
        "DocumentVersion": {"title": "Version", "description": "Version des Dateiinhalts",
                            "felder": {"version_number": ("int", "Version", "Nummer"), "sha256": ("text", "Prüfsumme", "SHA-256"), "size_bytes": ("int", "Grösse", "Bytes"),
                                       "page_count": ("int?", "Seiten", "bei PDF"), "pdfa_level": ("text?", "PDF/A", "nach Umwandlung"),
                                       "origin": ("enum:upload=hochgeladen;edit=bearbeitet;conversion=umgewandelt;signature=signiert;seal=versiegelt;cloud=aus der Cloud-Ablage;module=aus einem Modul", "Herkunft", "Art der Version"),
                                       "created_at": ("datetime", "Erstellt am", "Zeitpunkt")}},
        "Annotation": {"title": "Anmerkung", "description": "Anmerkung oder Formularwert auf einem PDF",
                       "felder": {"id": ("uuid!", "ID", "UUID v7"), "annotation_type": ("enum:text=Text;comment=Kommentar;date=Datum;signature_field=Unterschriftsfeld;form_value=Formularwert;seal=Siegel;checkmark=Haken", "Art", "Werkzeug"),
                                  "page_index": ("int", "Seite", "ab 0"), "x_percent": ("decimal", "Position links (%)", "relativ"), "y_percent": ("decimal", "Position oben (%)", "relativ"),
                                  "width_percent": ("decimal?", "Breite (%)", "relativ"), "height_percent": ("decimal?", "Höhe (%)", "relativ"), "content": ("text?", "Inhalt", "Text, Datum oder Wert"),
                                  "form_field_name": ("text?", "Formularfeld", "Name im PDF")}, "pflicht": ["annotation_type", "page_index", "x_percent", "y_percent"]},
        "AnnotationSet": {"title": "Anmerkungen", "description": "alle Anmerkungen eines Dokuments", "felder": {"annotations": ("list:ref:Annotation", "Anmerkungen", "ersetzt den bisherigen Stand")}, "pflicht": ["annotations"]},
        "WordContent": {"title": "Word-Inhalt", "description": "bearbeitbarer Inhalt eines Word-Dokuments", "felder": {"paragraphs": ("list:object", "Absätze", "Stil (h1, h2, p) und Inhalt")}, "pflicht": ["paragraphs"]},
        "PdfaConversion": {"title": "PDF/A-Umwandlung", "description": "Optionen der Umwandlung",
                           "felder": {"keep_copy": ("bool", "PDF/A ablegen", "Kopie behalten"), "flatten_annotations": ("bool", "Anmerkungen einbrennen", "fest ins PDF")}},
        "DocumentCopy": {"title": "Kopie", "description": "bearbeitbare Kopie, z. B. ohne Signaturen", "felder": {"folder_id": ("uuid?", "Ordner", "Ziel"), "name": ("text?", "Dateiname", "neuer Name")}},
        "ModuleSignatureRequest": {"title": "Signaturanfrage eines Moduls", "description": "Dokument und Unterzeichnende in einem Aufruf",
                                   "felder": {"title": ("text", "Titel", "Betreff"), "file_base64": ("text", "Datei", "PDF/A, Word oder Excel, Base64"), "file_name": ("text", "Dateiname", "mit Endung"),
                                              "signature_level": (STUFE, "Signaturstufe", "verlangt"), "jurisdiction": (RAUM, "Rechtsraum", "Signaturrecht"),
                                              "participants": ("list:ref:Participant", "Beteiligte", "Personen"), "fields": ("list:ref:SignatureField", "Unterschriftsfelder", "leer = Platzhalter verwenden"),
                                              "message": ("text?", "Nachricht", "an die Unterzeichnenden"), "due_on": ("date?", "Frist", "Unterschrift bis"), "seal_after": ("bool", "Versiegeln", "nach Abschluss"),
                                              "callback_url": ("url", "Rückmeldung an", "Adresse im Modul"), "idempotency_key": ("text", "Idempotenzschlüssel", "verhindert Doppelanfragen")},
                                   "pflicht": ["title", "file_base64", "file_name", "signature_level", "participants", "callback_url", "idempotency_key"]},
        "SignatureRequest": {"title": "Signaturanfrage", "description": "Anfrage an mich (Eingang «Zu unterschreiben»)",
                             "felder": {"id": ("uuid", "ID", "UUID v7"), "source_module": ("text", "Modul", "Modulschlüssel"), "sender_label": ("text", "Von", "Absender"), "title": ("text", "Titel", "Betreff"),
                                        "file_name": ("text", "Datei", "Dateiname"), "received_at": ("datetime", "Erhalten am", "Eingang"), "due_on": ("date?", "Frist", "Unterschrift bis"),
                                        "signature_level": (STUFE, "Signaturstufe", "verlangt"), "jurisdiction": (RAUM, "Rechtsraum", "Signaturrecht"),
                                        "status": ("enum:open=offen;signed=signiert;declined=abgelehnt;expired=abgelaufen", "Status", "Stand"), "message": ("text?", "Nachricht", "vom Absender"),
                                        "signed_by": ("list:ref:SignatureProof", "Bereits unterschrieben", "andere Personen")}},
        "SigningAction": {"title": "Unterschreiben", "description": "Unterschrift leisten oder ablehnen",
                          "felder": {"verification_code": ("text?", "Bestätigungscode", "bei FES aufs Mobiltelefon"), "is_declined": ("bool", "Ablehnen", "statt unterschreiben"), "decline_reason": ("text?", "Begründung", "bei Ablehnung")}},
        "SealRequest": {"title": "Versiegeln", "description": "Dokument mit dem Organisationssiegel versehen",
                        "felder": {"document_id": ("uuid?", "Dokument", "aus der Ablage"), "file_base64": ("text?", "Datei", "für Module ohne Ablage"),
                                   "seal_level": ("enum:advanced=fortgeschritten;qualified=qualifiziert", "Stufe", "rechtliche Wirkung"), "jurisdiction": (RAUM, "Rechtsraum", "Signaturrecht"),
                                   "is_visible": ("bool", "Sichtbar", "Siegelbild auf der letzten Seite")}, "pflicht": ["seal_level", "jurisdiction"]},
        "VerificationReport": {"title": "Prüfbericht", "description": "Signaturen und Siegel eines PDF",
                               "felder": {"is_valid": ("bool", "Gültig", "alle Signaturen gültig"), "pdfa_level": ("text?", "PDF/A", "erkannte Stufe"), "signatures": ("list:ref:SignatureProof", "Signaturen", "Nachweise"),
                                          "seals": ("list:ref:SealProof", "Siegel", "Nachweise"), "notes": ("list:text", "Hinweise", "Befunde")}},
        "SyncSettings": {"title": "Abgleich", "description": "Einstellungen und Stand des Abgleichs mit der Cloud-Ablage",
                         "felder": {"is_active": ("bool", "Aktiv", "eingeschaltet"), "target_path": ("text", "Zielordner", "in der Cloud-Ablage"),
                                    "direction": ("enum:both=beide Richtungen;upload=nur hochladen;download=nur herunterladen", "Richtung", "Abgleich"), "interval_minutes": ("int", "Intervall (Minuten)", "Abstand"),
                                    "conflict_rule": ("enum:keep_both=beide behalten;local=lokal gewinnt;cloud=Cloud gewinnt;newer=neuere gewinnt", "Konfliktregel", "bei Änderungen auf beiden Seiten"),
                                    "last_synced_at": ("datetime?!", "Letzter Abgleich", "Zeitpunkt"), "pending_count": ("int!", "Ausstehend", "Anzahl"), "conflict_count": ("int!", "Konflikte", "Anzahl")},
                         "pflicht": ["is_active", "target_path"]},
        "SyncFolderState": {"title": "Ordnerabgleich", "description": "Stand je Ordner",
                            "felder": {"folder_path": ("text", "Ordner", "Pfad"), "local_count": ("int", "Hier", "Anzahl Dateien"), "cloud_count": ("int", "Cloud", "Anzahl Dateien"), "state": ("text", "Stand", "z. B. «abgeglichen»")}},
        "ConflictResolution": {"title": "Konflikt lösen", "description": "welche Fassung behalten wird",
                               "felder": {"keep": ("enum:local=lokal;cloud=Cloud;both=beide", "Behalten", "Entscheid")}, "pflicht": ["keep"]},
        "SigningPreferences": {"title": "Meine Unterschrift", "description": "persönliche Standardwerte",
                               "felder": {"signature_level": (STUFE, "Signaturstufe", "Vorgabe"), "jurisdiction": (RAUM, "Rechtsraum", "Vorgabe")}},
        "ProcessCompletedEvent": {"title": "Ereignis Prozess beendet", "description": "Rückruf an das anfragende Modul",
                                  "felder": {"signature_process_id": ("uuid", "Signaturprozess", "Verweis"), "idempotency_key": ("text", "Idempotenzschlüssel", "aus der Anfrage"),
                                             "status": ("enum:completed=abgeschlossen;declined=abgelehnt;expired=abgelaufen;withdrawn=zurückgezogen", "Status", "Ende"),
                                             "result_url": ("url?", "Ergebnis", "signiertes Dokument"), "signatures": ("list:ref:SignatureProof", "Signaturen", "Nachweise")}},
    },
    "aktionen": [
        {"pfad": f"{M}/documents/upload", "op": "uploadDocument", "summary": "Datei hochladen", "ressource": "documents", "beschreibung": "Auch per Drag & Drop; Virenprüfung und Prüfsumme.",
         "body": "datei", "formfelder": {"folder_id": ("uuid?", "Ordner", "Ziel"), "name": ("text?", "Dateiname", "sonst Originalname")}, "antwort": "Document", "code": "201", "klassen": ["personal"]},
        {"pfad": f"{M}/documents/{{id}}/content", "methode": "get", "op": "getDocumentContent", "summary": "Inhalt herunterladen", "ressource": "documents",
         "query": [("version_number", "int", "Version", "leer = aktuelle")], "antwort": "datei:application/octet-stream", "klassen": ["personal"], "fehler": ("401", "403", "404")},
        {"pfad": f"{M}/documents/{{id}}/content", "methode": "put", "op": "replaceDocumentContent", "summary": "Neuen Inhalt speichern", "ressource": "documents",
         "body": "datei", "antwort": "Document", "ifmatch": True, "klassen": ["personal"]},
        {"pfad": f"{M}/documents/{{id}}/versions", "methode": "get", "op": "listDocumentVersions", "summary": "Versionen eines Dokuments", "ressource": "documents",
         "antwort": "liste:DocumentVersion", "fehler": ("401", "403", "404")},
        {"pfad": f"{M}/documents/{{id}}/copy", "op": "copyDocument", "summary": "Bearbeitbare Kopie anlegen", "ressource": "documents", "body": "DocumentCopy", "antwort": "Document", "code": "201", "klassen": ["personal"]},
        {"pfad": f"{M}/documents/{{id}}/annotations", "methode": "get", "op": "listAnnotations", "summary": "Anmerkungen und Formularwerte", "ressource": "annotations",
         "antwort": "liste:Annotation", "klassen": ["personal"], "fehler": ("401", "403", "404")},
        {"pfad": f"{M}/documents/{{id}}/annotations", "methode": "put", "op": "replaceAnnotations", "summary": "Anmerkungen und Formularwerte speichern", "ressource": "annotations",
         "body": "AnnotationSet", "antwort": "liste:Annotation", "ifmatch": True, "klassen": ["personal"]},
        {"pfad": f"{M}/documents/{{id}}/word-content", "methode": "get", "op": "getWordContent", "summary": "Word-Inhalt zum Bearbeiten", "ressource": "documents", "antwort": "WordContent",
         "klassen": ["personal"], "fehler": ("401", "403", "404", "409")},
        {"pfad": f"{M}/documents/{{id}}/word-content", "methode": "put", "op": "saveWordContent", "summary": "Word-Inhalt speichern", "ressource": "documents", "body": "WordContent",
         "antwort": "Document", "ifmatch": True, "klassen": ["personal"]},
        {"pfad": f"{M}/documents/{{id}}/pdfa-conversion", "op": "convertToPdfa", "summary": "In PDF/A-2b umwandeln", "ressource": "documents", "body": "PdfaConversion", "antwort": "Document", "code": "201", "klassen": ["personal"]},
        {"pfad": f"{O}/signature-processes/{{id}}/placeholders", "op": "detectPlaceholders", "summary": "Platzhalter «#sign#n#» erkennen und Felder setzen", "antwort": "SignatureProcess"},
        {"pfad": f"{O}/signature-processes/{{id}}/sending", "op": "sendSignatureProcess", "summary": "Prozess senden", "beschreibung": "Prüft, dass jede unterschreibende Person ein Feld hat.",
         "antwort": "SignatureProcess", "ifmatch": True, "klassen": ["internal", "personal"]},
        {"pfad": f"{O}/signature-processes/{{id}}/reminder", "op": "remindParticipants", "summary": "Offene Beteiligte erinnern", "antwort": "SignatureProcess"},
        {"pfad": f"{O}/signature-processes/{{id}}/withdrawal", "op": "withdrawSignatureProcess", "summary": "Laufenden Prozess zurückziehen", "antwort": "SignatureProcess", "ifmatch": True},
        {"pfad": f"{O}/signature-processes/module-requests", "op": "createModuleSignatureRequest", "summary": "Signaturanfrage aus einem Modul", "ressource": "signature-processes",
         "beschreibung": "Idempotent über den Idempotenzschlüssel; Ergebnis per Rückruf «sign.process.completed».", "body": "ModuleSignatureRequest", "antwort": "SignatureProcess", "code": "201",
         "klassen": ["internal", "personal"]},
        {"pfad": f"{M}/signature-requests", "methode": "get", "op": "listMySignatureRequests", "summary": "Zu unterschreiben", "ressource": "signature-requests",
         "query": [("status", "text", "Status", "z. B. open")], "antwort": "liste:SignatureRequest", "klassen": ["personal"], "fehler": ("401", "403", "422")},
        {"pfad": f"{M}/signature-requests/{{id}}", "methode": "get", "op": "getMySignatureRequest", "summary": "Anfrage mit Dokument und Feldern", "ressource": "signature-requests",
         "antwort": "SignatureRequest", "klassen": ["personal"], "fehler": ("401", "403", "404")},
        {"pfad": f"{M}/signature-requests/{{id}}/signing", "op": "signMyRequest", "summary": "Unterschreiben oder ablehnen", "ressource": "signature-requests", "body": "SigningAction",
         "antwort": "SignatureRequest", "klassen": ["personal"]},
        {"pfad": f"{M}/signature-requests/{{id}}/verification-code", "op": "requestVerificationCode", "summary": "Bestätigungscode senden (FES)", "ressource": "signature-requests",
         "antwort": None, "code": "204", "klassen": ["personal"]},
        {"pfad": f"{O}/seals", "op": "sealDocument", "summary": "Mit dem Organisationssiegel versiegeln", "ressource": "seals", "recht": "admin", "beschreibung": "Ergebnis «<Name>_seal.pdf».",
         "body": "SealRequest", "antwort": "Document", "code": "201"},
        {"pfad": f"{O}/seals/verification", "op": "verifyPdf", "summary": "Signaturen und Siegel eines PDF prüfen", "ressource": "seals", "recht": "read", "body": "datei", "antwort": "VerificationReport", "klassen": ["personal"]},
        {"pfad": f"{M}/sync", "methode": "get", "op": "getSyncSettings", "summary": "Einstellungen und Stand des Abgleichs", "ressource": "sync", "antwort": "SyncSettings", "klassen": ["personal"], "fehler": ("401", "403")},
        {"pfad": f"{M}/sync", "methode": "put", "op": "saveSyncSettings", "summary": "Abgleich einstellen", "ressource": "sync", "body": "SyncSettings", "antwort": "SyncSettings", "klassen": ["personal"]},
        {"pfad": f"{M}/sync/run", "op": "runSync", "summary": "Jetzt abgleichen", "ressource": "sync", "antwort": "liste:SyncFolderState", "code": "202", "klassen": ["personal"]},
        {"pfad": f"{M}/sync/conflicts/{{id}}/resolution", "op": "resolveSyncConflict", "summary": "Konflikt lösen", "ressource": "sync", "body": "ConflictResolution", "antwort": "Document", "klassen": ["personal"]},
        {"pfad": f"{M}/signing-preferences", "methode": "get", "op": "getSigningPreferences", "summary": "Standard-Signaturstufe und Rechtsraum", "ressource": "preferences", "antwort": "SigningPreferences",
         "klassen": ["personal"], "fehler": ("401", "403")},
        {"pfad": f"{M}/signing-preferences", "methode": "put", "op": "saveSigningPreferences", "summary": "Standardwerte speichern", "ressource": "preferences", "body": "SigningPreferences",
         "antwort": "SigningPreferences", "klassen": ["personal"]},
    ],
    "ereignisse": {"sign.process.completed": ("ProcessCompletedEvent", "Signaturprozess beendet – Rückruf an das anfragende Modul")},
}
